// Task.js
// A task is generated by Grok AI for a specific project.
// Each task is assigned to one employee with a priority and status.

const mongoose = require("mongoose");

const TaskSchema = new mongoose.Schema(
  {
    // Which project this task belongs to
    projectId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "Project",
      required: true,
    },

    title: {
      type: String,
      required: true,
      trim: true,
    },

    description: {
      type: String,
      required: true,
    },

    // Which employee is responsible for this task
    assignedTo: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "User",
      default: null,
    },

    // How many days Grok estimated this will take
    estimatedDays: {
      type: Number,
      default: 1,
    },

    priority: {
      type: String,
      enum: ["high", "medium", "low"],
      default: "medium",
    },

    // Tracks task progress
    status: {
      type: String,
      enum: ["pending", "in_progress", "completed", "needs_revision"],
      default: "pending",
    },

    deadline: {
      type: Date,
      default: null,
    },
  },
  {
    timestamps: true,
  }
);

module.exports = mongoose.model("Task", TaskSchema);